css:
.cvch { display:inline-block; background:#2b3a8f; color:#fff; font-weight:700;
        font-size:17px; letter-spacing:.6px; border-radius:9px 13px 8px 12px;
        padding:2px 13px; transform:rotate(-1deg); }

.cvseal { flex:none; width:130px; height:130px; border-radius:50% 47% 53% 48%;
          background:radial-gradient(circle at 34% 28%,#fdf3b4,#f6c945);
          border:3px solid #e2b93b; display:flex; flex-direction:column;
          align-items:center; justify-content:center; transform:rotate(-4deg);
          box-shadow:2px 5px 14px rgba(0,0,0,.18); }

.cvhead { display:flex; justify-content:space-between; gap:12.5px; font-size:15.2px;
          font-weight:700; color:#8a8372; border-bottom:2px solid currentColor;
          padding-bottom:3px; margin-bottom:5px; opacity:.85; }

.cvtotal { display:flex; justify-content:space-between; align-items:center;
           margin-top:9.5px; padding-top:9px; border-top:2.5px solid #e78aa8;
           font-size:19.5px; font-weight:700; color:#c2337a; }

.cvformula { text-align:center; font-family:'Times New Roman',Times,serif; font-style:italic;
             font-size:38px; font-weight:700; color:#8a5a00; background:#fffdf3;
             border:2px dashed #e2b93b; border-radius:14px; padding:9.5px 0;
             font-variant-numeric:lining-nums; }

.cvstep .cvn { flex:none; width:28px; height:28px; border-radius:50% 45% 52% 47%;
               background:#3fae4e; color:#fff; font-size:16px; font-weight:700;
               display:flex; align-items:center; justify-content:center; margin-top:1px; }

/* COVER IN TWO PAGES, NOT THREE.
   The third cover page carried two cards and nothing else. Every size
   here is reduced by roughly a tenth to buy back that page — and
   NOTHING is taken below 15px, because 15 x 0.734 print zoom is 11px,
   the legibility floor. `.cvhead` and `.cvmk` are already at the floor
   and are left alone. Scoped to maths so the physics and biology
   covers, which already fit, are untouched. */
.subj-maths .cvname   { font-size:46px; }
.subj-maths .cvsn     { font-size:44px; }
.subj-maths .cvformula{ font-size:31px; padding:7px 0; }
.subj-maths .cvh      { font-size:27px; margin-bottom:8px; }
.subj-maths .cvlead   { font-size:19px; margin-top:9px; }
.subj-maths .cvrow    { font-size:16.5px; padding:6px 0; }
.subj-maths .cvtxt    { font-size:16.5px; margin-top:9px; }
.subj-maths .cvstep   { font-size:16.5px; }
.subj-maths .cvnote   { font-size:16.5px; padding:11px 14px; }
.subj-maths .cvtotal  { font-size:18px; margin-top:8px; padding-top:7px; }
.subj-maths .cvchip   { font-size:15.5px; padding:2px 11px; }

/* TWELVE PIXELS DECIDED A WHOLE SHEET.
   Balanced, the maths cover's spill cards measure ~1444px against a
   1432px sheet — over by the inter-card gaps alone, which is what
   pushed two short cards onto a third page. Tightening the gap and
   the grid's top margin buys ~40px per column: enough, and it costs
   no type size, so nothing crosses the 11px print floor. */
.subj-maths .cvcol  { gap:9px; }
.subj-maths .cvgrid { gap:20px; margin-top:14px; }

/* The chapter masthead — board, class, subject. Small and quiet: it
   is the same on every chapter, so it identifies the book rather
   than this chapter, and it must not compete with the title above
   it. 15.5px prints at 11.4px, just clear of the floor. */
.cvmast { font-size:15.5px; font-weight:600; color:#6b7383;
          letter-spacing:.2px; margin-top:4px; }

/* Each paragraph of a cover note — see `components/cover.note`. The
   chapter's reading guide is a heading plus four labelled items, and
   flattened into one run they read as a single sentence. */
.cvnote-p + .cvnote-p { margin-top:5px; }
